(x, y, t) => {
  const cx = 240, cy = 120;
  let wx = Math.sin(x*0.02+t*0.3)*15 + Math.cos(y*0.015-t*0.2)*10;
  let wy = Math.cos(y*0.02-t*0.25)*15 + Math.sin(x*0.018+t*0.35)*10;
  const wx2 = Math.sin((x+wx)*0.012-t*0.15)*20 + Math.cos((y+wy)*0.01+t*0.18)*15;
  const wy2 = Math.cos((y+wy)*0.013+t*0.12)*20 + Math.sin((x+wx)*0.011-t*0.2)*15;
  const sx = x+wx+wx2, sy = y+wy+wy2;
  const src = [
    [160+Math.sin(t*0.6)*100, 80+Math.cos(t*0.4)*50, 0.08, 2.0],
    [320+Math.cos(t*0.5)*100, 160+Math.sin(t*0.7)*50, 0.1, 1.7],
    [240+Math.sin(t*0.3+2)*140, 120+Math.cos(t*0.5+1)*90, 0.06, 2.3],
    [120+Math.cos(t*0.8+1)*80, 180+Math.sin(t*0.6+3)*60, 0.12, 1.5],
    [360+Math.sin(t*0.4+4)*90, 60+Math.cos(t*0.9+2)*70, 0.07, 2.6],
    [240+Math.cos(t*0.35+5)*120, 200+Math.sin(t*0.55)*80, 0.09, 1.9],
    [80+Math.sin(t*0.45+3)*70, 40+Math.cos(t*0.65+2)*50, 0.14, 1.3],
    [400+Math.cos(t*0.55+1)*60, 200+Math.sin(t*0.75+4)*45, 0.11, 1.8]
  ];
  let aS=0, iS=0, aS2=0, iS2=0;
  for (const [sX,sY,f,sp] of src) {
    const d = Math.sqrt((sx-sX)**2+(sy-sY)**2);
    aS += Math.sin(d*f-t*sp);
    iS += Math.sin(d*f*0.7+t*sp*0.6+1.5);
    aS2 += Math.sin(d*f*1.8-t*sp*1.4+0.7)*0.5;
    iS2 += Math.sin(d*f*1.3+t*sp*0.9+2.8)*0.4;
  }
  const act=aS/8, inh=iS/8, act2=aS2/8, inh2=iS2/8;
  const bg = (Math.sin(sx*0.04+sy*0.025+t*0.8)+Math.sin(sx*0.03-sy*0.04+t*1.1))/2
    + Math.sin((sx+sy)*0.12+t*2.5)*0.2 + Math.sin((sx-sy)*0.1-t*2)*0.2;
  const dist = Math.sqrt((sx-cx)**2+(sy-cy)**2), ang = Math.atan2(sy-cy, sx-cx);
  const spiral = (Math.sin(dist*0.05-ang*3-t*1.5)+Math.sin(dist*0.04+ang*4-t*1.2))*0.4;
  const spiral2 = (Math.sin(dist*0.08+ang*5+t*0.9)+Math.sin(dist*0.06-ang*2+t*1.8))*0.25;
  const vein = Math.sin(Math.sin(sx*0.08+bg)*8+Math.cos(sy*0.07-spiral)*8+t)*0.3;
  const macro = Math.tanh((act-inh*0.7+bg*0.3+spiral)*2.2);
  const micro = Math.tanh((act2-inh2*0.6+spiral2+vein)*1.8)*0.6;
  const cell = Math.tanh((Math.sin(sx*0.15)*Math.sin(sy*0.15)+Math.sin((sx+sy)*0.1+t)*0.5)*1.5)*0.3;
  const grain = Math.sin(sx*0.5+t*3)*Math.sin(sy*0.5-t*2.7)*0.08;
  const blend = macro*0.55+micro*0.2+cell*0.2+grain*0.05;
  const v = blend*0.5+0.5;
  const pal = [
    [5,12,52],[12,45,85],[18,90,105],[30,150,130],
    [180,195,60],[220,155,50],[195,85,55],[145,40,65],
    [90,22,72],[40,15,58],[5,12,52]
  ];
  const idx = v*(pal.length-1), i = Math.min(idx|0, pal.length-2), f = idx-i;
  const lum = 0.85+Math.sin(macro*Math.PI)*0.15;
  const edge = Math.abs(macro)>0.65?1.12:Math.abs(micro)>0.5?1.06:1.0;
  const shimmer = 1.0+Math.sin(ang*6+dist*0.03-t*2)*0.04*Math.max(0,macro);
  return [
    Math.min(255, (pal[i][0]+(pal[i+1][0]-pal[i][0])*f)*lum*edge*shimmer)|0,
    Math.min(255, (pal[i][1]+(pal[i+1][1]-pal[i][1])*f)*lum*edge*shimmer)|0,
    Math.min(255, (pal[i][2]+(pal[i+1][2]-pal[i][2])*f)*lum*edge*shimmer)|0
  ];
}
